import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"First Launch","description":"Start the control plane with npx; the first start downloads the binary and writes the config file.","frontmatter":{"title":"First Launch","description":"Start the control plane with npx; the first start downloads the binary and writes the config file."},"headers":[],"relativePath":"getting-started/first-launch.md","filePath":"getting-started/first-launch.md"}'),o={name:"getting-started/first-launch.md"};function i(r,e,l,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h1><p>Run either name; both start the same app:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlsf</span></span></code></pre></div><p>The first start installs the prebuilt binary for your machine: the installer says it is downloading, takes the binary from the release&#39;s GitHub Release, verifies its SHA-256 against the release&#39;s checksums file, and keeps it under your data home, in a directory per target - <code>~/.local/share/my-little-software-factory/bin/&lt;target&gt;/factory</code>, or <code>%LOCALAPPDATA%\\my-little-software-factory\\bin\\&lt;target&gt;\\factory.exe</code> on Windows. The binary&#39;s <code>.install</code> note beside it names the version, the target, and the SHA-256 it was verified against. A second start finds the cached binary, checks its bytes against that note, and skips the network; a new release version, a note for another target, and a binary someone else wrote over all download the right one again.</p><p>The download is about 100 MB and has a time bound of its own. On a slow link, raise the bound with <code>MLSF_DOWNLOAD_TIMEOUT_MS</code>, in milliseconds: <code>MLSF_DOWNLOAD_TIMEOUT_MS=1800000 npx mlsf</code>.</p><p>To drop the cache, delete the data-home directory: <code>rm -rf ~/.local/share/my-little-software-factory</code>.</p><p>The control plane then finds no config file, writes the <a href="./minimal-config.html#the-config-file">Default configuration</a> to <code>~/.config/my-little-software-factory/config.toml</code>, and says so on the start lines before the interface appears. The start lines name the path, so you know where to edit.</p><p>A second start reads the file. A line that does not parse or does not validate stops the start with one readable error line. A present file must carry every required key, and a key the control plane does not read is an error, so a typo surfaces at the start, not at handoff time.</p><p>The binary answers <code>factory --version</code> with the version the release stamped into it, and <code>factory --config &lt;path&gt;</code> starts on the config file you name. Both flags work before any config exists. <code>--version</code> on a machine that has not downloaded the binary yet is answered by the installer, from the package version, so the flag costs no download; once the binary is cached the same flag goes to the binary itself.</p><p>An install you keep uses the same launcher: <code>npm install -g my-little-software-factory</code> puts a <code>factory</code> command on your <code>PATH</code>, and it installs and runs the binary the way <code>npx</code> does.</p><p>Next: <a href="./minimal-config.html">the minimal config</a>.</p>`,11)])])}const y=t(o,[["render",i]]);export{p as __pageData,y as default};
